import{_ as e,o as a,c as o,a0 as r}from"./chunks/framework.DCluYYrN.js";const p=JSON.parse('{"title":"界面与外观","description":"FoxSu 管理器的五套皮肤、13 种底栏与定制中心。","frontmatter":{"title":"界面与外观","description":"FoxSu 管理器的五套皮肤、13 种底栏与定制中心。","outline":"deep"},"headers":[],"relativePath":"zh_CN/features.md","filePath":"zh_CN/features.md"}'),d={name:"zh_CN/features.md"};function l(i,t,h,n,s,c){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="界面与外观" tabindex="-1">界面与外观 <a class="header-anchor" href="#界面与外观" aria-label="Permalink to &quot;界面与外观&quot;">​</a></h1><p>FoxSu 的内核沿用 KernelSU，管理器则是整套重写的。这一页讲的是后者——你每天真正会看到、会摸到的那部分。</p><blockquote><p>Root 在内核，体验在管理器。</p></blockquote><h2 id="五套皮肤" tabindex="-1">五套皮肤 <a class="header-anchor" href="#五套皮肤" aria-label="Permalink to &quot;五套皮肤&quot;">​</a></h2><p>在「设置 → 界面风格」里切换。切换是全局的：主页、模块、日志、设置，所有页面同时换掉排版，不是只换一张壁纸。</p><table tabindex="0"><thead><tr><th>皮肤</th><th>排版语言</th><th>特点</th></tr></thead><tbody><tr><td><strong>Redesign</strong>（Miuix）</td><td>玻璃卡片 + 胶囊底栏</td><td>默认皮肤，信息密度最高，主页是一张主卡加四张 KPI 卡</td></tr><tr><td><strong>Editorial</strong></td><td>杂志排版</td><td>纸面底色、墨线分隔、衬线标题，自带原生底栏，也可换成胶囊</td></tr><tr><td><strong>Pages</strong>（Fresh）</td><td>大留白</td><td>大标题加分区块列表，适合单手浏览</td></tr><tr><td><strong>Glass</strong></td><td>液态玻璃</td><td>通透卡面、浅色高光，配壁纸观感最好</td></tr><tr><td><strong>Nocturne</strong></td><td>暗夜霓虹</td><td>深色优先，霓虹描边与发光强调色</td></tr></tbody></table><p>五套皮肤共享同一套功能与设置项，切换不会丢配置。</p><h2 id="_13-种底栏" tabindex="-1">13 种底栏 <a class="header-anchor" href="#_13-种底栏" aria-label="Permalink to &quot;13 种底栏&quot;">​</a></h2><p>底栏不再跟着皮肤走，而是全局独立的选项：</p><p><code>原有胶囊</code> · <code>展开药丸</code> · <code>侧边抽屉</code> · <code>流光光标</code> · <code>描边霓虹</code> · <code>方块卡片</code> · <code>渐变实底</code> · <code>顶指示条</code> · <code>浮起圆片</code> · <code>纸面墨线</code> · <code>白色药丸</code> · <code>液态药丸</code> · <code>暗夜霓虹</code></p><p>选择侧边抽屉模式时，每页内容会自动让出左侧空间，不会被胶囊压住。</p><h2 id="定制中心" tabindex="-1">定制中心 <a class="header-anchor" href="#定制中心" aria-label="Permalink to &quot;定制中心&quot;">​</a></h2><p>所有外观项都接真实设置，改完即时生效，不需要重启。</p><h3 id="壁纸" tabindex="-1">壁纸 <a class="header-anchor" href="#壁纸" aria-label="Permalink to &quot;壁纸&quot;">​</a></h3><ul><li>从相册选取，支持拖动裁剪与缩放</li><li>可单独压暗，保证前景文字可读</li><li>可以彻底关掉全局背景图，回到纯色</li></ul><h3 id="卡面" tabindex="-1">卡面 <a class="header-anchor" href="#卡面" aria-label="Permalink to &quot;卡面&quot;">​</a></h3><ul><li><strong>配图</strong>：主页大卡、四张 KPI 卡、每个模块卡都能单独配图，透明度独立可调</li><li><strong>配色</strong>：全局取色加单卡覆盖，另有一键七彩卡片</li><li><strong>圆角</strong>：全局圆角统一调整</li></ul><h3 id="字体" tabindex="-1">字体 <a class="header-anchor" href="#字体" aria-label="Permalink to &quot;字体&quot;">​</a></h3><p>系统默认、衬线、等宽、手写圆体四种预设，也可以导入自己的字体文件。</p><h3 id="标题与图标" tabindex="-1">标题与图标 <a class="header-anchor" href="#标题与图标" aria-label="Permalink to &quot;标题与图标&quot;">​</a></h3><ul><li>主页顶部标题可自定义文案</li><li>启动器图标有四套狐狸形象，随系统主题切换深浅</li><li>图标造型支持圆角方、正圆、超椭圆、七彩渐变</li></ul><h3 id="光感" tabindex="-1">光感 <a class="header-anchor" href="#光感" aria-label="Permalink to &quot;光感&quot;">​</a></h3><p>沉浸光感、液态玻璃、七彩图标、莫奈取色，逐项独立开关，可以只开其中一两个。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/FoxSu/zh_CN/guide/installation.html">安装 FoxSu</a></li><li><a href="/FoxSu/zh_CN/guide/app-profile.html">App Profile 与权限控制</a></li><li><a href="/FoxSu/zh_CN/guide/module.html">模块开发指南</a></li></ul>',25)])])}const _=e(d,[["render",l]]);export{p as __pageData,_ as default};
